'use strict';
let currentUser=null;
async function api(path,data){const response=await fetch('/api/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-Nail-Request':'1'}:{},body:data?JSON.stringify(data):undefined});const result=await response.json();if(!response.ok)throw Error(result.error||'Không kết nối được');return result;}
async function refreshState(){const result=await api('state');currentUser=result.user;state={employees:result.employees,shifts:result.shifts,pending:result.pending||[]};applyRole();render();renderPending();if(typeof loadMyProfile==='function')await loadMyProfile();if(page==='orders'&&currentUser.role==='manager')await loadOrders();if(page==='employees'&&currentUser.role==='manager')await loadEmployees();}
function applyRole(){const manager=currentUser.role==='manager';document.body.classList.toggle('employee-mode',!manager);document.body.classList.add('authenticated');$('authPanel').hidden=true;$('accountName').textContent=currentUser.name;$('accountRole').textContent=manager?'Quản lý':'Nhân viên';for(const id of ['addEmployee','addShift','ordersNav','employeesNav'])$(id).hidden=!manager;if(!manager&&['orders','employees'].includes(page))document.querySelector('[data-page="clock"]').click();document.querySelector('.side-bottom').innerHTML='<span class="dot"></span> Dữ liệu lưu trên máy chủ<small>Phiên đăng nhập tối đa 12 giờ</small>';document.querySelector('footer').innerHTML='Ca đang mở chưa tính vào tổng giờ. Ca qua đêm được ghi nhận theo ngày bắt đầu.<br><span>'+(manager?'Quản lý có thể tạo tài khoản và chỉnh sửa ca.':'Chỉ quản lý được chấm công. Nhân viên xem ca và lương của mình.')+'</span>';}
async function showAuth(){document.body.classList.remove('authenticated');$('authPanel').hidden=false;currentUser=null;if(typeof clearOrders==='function')clearOrders();state={employees:[],shifts:[]};render();$('authTitle').textContent='Chào mừng bạn trở lại.';$('authHint').textContent='Đăng nhập để bắt đầu ca làm của bạn.';$('authSubmit').textContent='Đăng nhập';try{const status=await api('status');if(status.user)return refreshState();$('openManagerActivation').hidden=!status.managerAccounts?.length;$('managerActivationForm').elements.username.innerHTML=(status.managerAccounts||[]).map(n=>'<option value="'+esc(n)+'">'+esc(n)+'</option>').join('');}catch{$('authError').textContent='Hãy chạy START-WEB.cmd rồi mở http://localhost:8081. Bản đăng nhập không chạy bằng cách mở tệp HTML trực tiếp.';}}
$('authForm').onsubmit=async event=>{event.preventDefault();const f=event.target,b=$('authSubmit');b.disabled=true;$('authError').textContent='';try{await api('login',{username:f.elements.username.value,password:f.elements.password.value});f.reset();await refreshState();}catch(e){$('authError').textContent=e.message;}finally{b.disabled=false;}};
$('openRegister').onclick=()=>{$('registerError').textContent='';$('registerDialog').showModal();};
$('registerForm').onsubmit=async event=>{event.preventDefault();const f=event.target,b=f.querySelector('button.primary');b.disabled=true;try{await api('register',{name:f.elements.name.value,username:f.elements.username.value,password:f.elements.password.value,email:f.elements.email.value,phone:f.elements.phone.value});f.reset();$('registerDialog').close();toast('Đã gửi email xác nhận, kiểm tra hộp thư và thư rác');}catch(e){$('registerError').textContent=e.message;}finally{b.disabled=false;}};
$('openManagerActivation').onclick=()=>{$('managerActivationError').textContent='';$('managerActivationDialog').showModal();};
$('managerActivationForm').onsubmit=async event=>{event.preventDefault();const f=event.target,b=f.querySelector('button.primary');b.disabled=true;try{await api('setup',{name:f.elements.name.value,username:f.elements.username.value,password:f.elements.password.value,setupKey:f.elements.setupKey.value,email:f.elements.email.value,phone:f.elements.phone.value});f.reset();$('managerActivationDialog').close();toast('Đã gửi email xác nhận, kiểm tra hộp thư và thư rác');await showAuth();}catch(e){$('managerActivationError').textContent=e.message;}finally{b.disabled=false;}};
$('logout').onclick=async()=>{try{await api('logout',{});await showAuth();}catch(e){toast(e.message);}};
$('changePassword').onclick=()=>$('passwordDialog').showModal();
$('refreshData').onclick=async()=>{const button=$('refreshData');button.disabled=true;try{await refreshState();toast('Đã làm mới dữ liệu');}catch(e){toast(e.message);}finally{button.disabled=false;}};
$('reports').addEventListener('click',event=>{const button=event.target.closest('[data-rate]');if(!button)return;const employee=state.employees.find(e=>e.id===button.dataset.rate);const form=$('rateForm');form.elements.employee.value=employee.id;form.elements.rate.value=employee.rateCents==null?'':(employee.rateCents/100).toFixed(2);$('rateName').textContent=employee.name;$('rateError').textContent='';$('rateDialog').showModal();});
$('rateForm').onsubmit=async event=>{event.preventDefault();const form=event.target,button=form.querySelector('button.primary');button.disabled=true;try{await api('pay-rate',{employee:form.elements.employee.value,rate:form.elements.rate.value});$('rateDialog').close();await refreshState();toast('Đã lưu mức lương');}catch(e){$('rateError').textContent=e.message;}finally{button.disabled=false;}};
$('passwordForm').onsubmit=async event=>{event.preventDefault();const f=event.target;try{await api('password',{current:f.elements.current.value,password:f.elements.password.value});f.reset();$('passwordDialog').close();toast('Đã đổi mật khẩu');}catch(e){$('passwordError').textContent=e.message;}};
showAuth();


function renderPending(){const pending=state.pending||[],panel=$('pendingAccounts');panel.hidden=currentUser?.role!=='manager'||!pending.length;panel.innerHTML='<h2>Tài khoản chờ duyệt</h2>'+pending.map(e=>'<article class="staff-card"><span data-no-translate>'+esc(e.name)+' ('+esc(e.username)+')</span> <button class="outline" data-approve="'+esc(e.id)+'">Duyệt nhân viên</button></article>').join('');}
$('pendingAccounts').onclick=async event=>{const b=event.target.closest('[data-approve]');if(!b)return;b.disabled=true;try{await api('approve',{employee:b.dataset.approve});await refreshState();toast('Đã duyệt nhân viên');}catch(e){toast(e.message);b.disabled=false;}};


